// Copies the Owarelin color tokens (`--ow-color-*`) from the IkaDoc frontend's stylesheet into
// `app/common/themes/owarelinTokens.ts`. Development only; the generated file is committed.
//
//   node devtools/owarelin-theme-tokens/generate.mjs [path/to/_owarelin-material-theme.scss]

import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join, relative, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const REPO = resolve(dirname(fileURLToPath(import.meta.url)), "../..");
const OUTPUT = join(REPO, "app/common/themes/owarelinTokens.ts");

const DEFAULT_SOURCE = resolve(
  REPO,
  "../ikadoc-ng/projects/shared/styles/_owarelin-material-theme.scss",
);

const source = resolve(process.argv[2] ?? DEFAULT_SOURCE);
const scss = readFileSync(source, "utf8");

// The stylesheet declares every token once for the light theme, then again for the dark one.
const light = {};
const dark = {};

for (const [, name, value] of scss.matchAll(/--ow-color-([a-z0-9-]+):\s*([^;]+);/g)) {
  const key = name.replace(/-([a-z0-9])/g, (_, letter) => letter.toUpperCase());

  if (!(key in light)) {
    light[key] = value.trim();
  } else if (!(key in dark)) {
    dark[key] = value.trim();
  }
}

const missingInDark = Object.keys(light).filter(key => !(key in dark));
if (Object.keys(light).length === 0 || missingInDark.length > 0) {
  throw new Error(
    `Unexpected token layout in ${source}; missing dark tokens: ${missingInDark.join(", ")}`,
  );
}

const lines = tokens => Object.entries(tokens)
  .map(([key, value]) => `    ${key}: "${value}",`)
  .join("\n");

const output = `// Generated by devtools/owarelin-theme-tokens/generate.mjs from
// ${relative(REPO, source)} — do not edit by hand.

export const OWARELIN_COLOR_TOKENS = {
  light: {
${lines(light)}
  },
  dark: {
${lines(dark)}
  },
} as const;

export type OwarelinColorTokens = Record<keyof typeof OWARELIN_COLOR_TOKENS.light, string>;
`;

writeFileSync(OUTPUT, output);

const tokenCount = Object.keys(light).length;
process.stdout.write(`wrote ${relative(REPO, OUTPUT)} (${tokenCount} tokens per appearance)\n`);
